function Header() {
  const [menuOpen, setMenuOpen] = useState(false)
  return <header className="site-header"><a className="brand" href="#/"><span className="brand-mark"><i></i><i></i><i></i></span><span>Luma<span>HR</span></span></a><button className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-expanded={menuOpen}>Menu</button><nav className={menuOpen ? 'nav open' : 'nav'} aria-label="Primary navigation"><a href="#/platform">Platform</a><a href="#/">Why Luma</a><a href="#/">Stories</a><a href="#/platform#demo" onClick={() => setMenuOpen(false)}>Pricing</a></nav><a className="login-link" href="#/login">Log in</a><a className="header-cta" href="#/signup">Start free</a></header>
}

function Footer() { return <footer><a className="brand" href="#/"><span className="brand-mark"><i></i><i></i><i></i></span><span>Luma<span>HR</span></span></a><p>HR software for the people behind the work.</p><span>© 2026 LumaHR</span></footer> }

function AuthPage({ mode }) {
  const isSignup = mode === 'signup'
  const [showPassword, setShowPassword] = useState(false)
  const [success, setSuccess] = useState(false)
  const [error, setError] = useState(''); const [loading, setLoading] = useState(false)
  async function submit(event) { event.preventDefault(); setError(''); setLoading(true); const form = new FormData(event.currentTarget); try { const me = await authenticate(isSignup ? '/auth/signup' : '/auth/login', isSignup ? { full_name: form.get('full-name'), company_name: form.get('company'), work_email: form.get('email'), password: form.get('password') } : { email: form.get('email'), password: form.get('password') }); window.location.hash = !me.company_id ? '#/onboarding/company' : !me.is_onboarded ? `#/onboarding/${me.onboarding_step || 'organization'}` : '#/dashboard' } catch (err) { setError(err.message) } finally { setLoading(false) } }
  return <main className="auth-page"><div className="auth-brand-panel"><a className="brand auth-brand" href="#/"><span className="brand-mark"><i></i><i></i><i></i></span><span>Luma<span>HR</span></span></a><div className="auth-message"><p className="eyebrow">{isSignup ? 'Start your people-first chapter' : 'Welcome back'}</p><h1>{isSignup ? 'Good work starts with a better workday.' : 'Your team is doing great things.'}</h1><p>{isSignup ? 'Bring your people, time and growth into one beautifully connected place.' : 'Sign in to pick up where your people work left off.'}</p></div></div><div className="auth-form-panel"><a className="back-home" href="#/">← Back to website</a><section className="auth-card"><p className="eyebrow">{isSignup ? 'Create your workspace' : 'Sign in to LumaHR'}</p><h2>{isSignup ? 'Let’s get started.' : 'Good to see you.'}</h2><p className="auth-subtitle">{isSignup ? 'Start with a 14-day free trial. No card required.' : 'New to LumaHR?'} {!isSignup && <a href="#/signup">Create an account</a>}</p><form className="auth-form" onSubmit={submit}>{isSignup && <><label>Full name</label><input name="full-name" required placeholder="Your full name"/><label>Company name</label><input name="company" required placeholder="Your company"/></>}<label>Work email</label><input name="email" required type="email" placeholder="you@company.com"/><label>Password</label><div className="password-field"><input name="password" required minLength="8" type={showPassword ? 'text' : 'password'} placeholder="At least 8 characters"/><button type="button" onClick={() => setShowPassword(!showPassword)}>{showPassword ? 'Hide' : 'Show'}</button></div>{!isSignup && <a className="forgot-link" href="#/forgot-password">Forgot password?</a>}{error && <p className="form-error">{error}</p>}<button className="primary-button auth-submit" disabled={loading}>{loading ? 'Please wait…' : isSignup ? 'Create your account' : 'Sign in to LumaHR'}</button></form>{!isSignup && <div className="demo-login"><div><span>Frontend demo access</span><small>Open a workspace without backend login.</small></div><div className="demo-login-grid">{[['employee', 'Employee', 'Maya Allen'], ['manager', 'Manager', 'Aisha Rao'], ['hr', 'HR / Admin', 'Nisha Agarwal']].map(([role, label, person]) => <button key={role} onClick={() => { window.location.hash = `#/dashboard?role=${role}` }}><b>{label}</b><small>{person}</small><i>Open</i></button>)}</div></div>}<p className="switch-auth">{isSignup ? 'Already have an account?' : 'Need a LumaHR account?'} <a href={isSignup ? '#/login' : '#/signup'}>{isSignup ? 'Log in' : 'Create one'}</a></p></section></div></main>
}

function PasswordPage({ reset = false }) {
  const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false)
  async function submit(event) { event.preventDefault(); setLoading(true); setError(''); const form = new FormData(event.currentTarget); try { if (reset) await api.post(ENDPOINTS.auth.resetPassword, { token: form.get('token'), new_password: form.get('password') }); else await api.post(ENDPOINTS.auth.forgotPassword, { email: form.get('email') }); setMessage(reset ? 'Your password has been reset. You can sign in now.' : 'If that email exists, we have sent reset instructions.') } catch (err) { setError(err.message) } finally { setLoading(false) } }
  return <main className="auth-page"><div className="auth-brand-panel"><a className="brand auth-brand" href="#/"><span className="brand-mark"><i></i><i></i><i></i></span><span>Luma<span>HR</span></span></a><div className="auth-message"><p className="eyebrow">Account security</p><h1>{reset ? 'Choose a new password.' : 'We’ll help you get back in.'}</h1></div></div><div className="auth-form-panel"><a className="back-home" href="#/login">← Back to login</a><section className="auth-card"><p className="eyebrow">{reset ? 'Reset password' : 'Forgot password'}</p><h2>{reset ? 'Set a new password.' : 'Check your inbox.'}</h2><p className="auth-subtitle">{reset ? 'Use the reset token from your email to continue.' : 'Enter your work email and we’ll send a reset link.'}</p><form className="auth-form" onSubmit={submit}>{reset ? <><label>Reset token</label><input name="token" required placeholder="Paste token from email"/><label>New password</label><input name="password" type="password" minLength="8" required placeholder="At least 8 characters"/></> : <><label>Work email</label><input name="email" type="email" required placeholder="you@company.com"/></>}{error && <p className="form-error">{error}</p>}{message && <p className="form-success">{message}</p>}<button className="primary-button auth-submit" disabled={loading}>{loading ? 'Please wait…' : reset ? 'Reset password' : 'Send reset link'}</button></form><p className="switch-auth"><a href="#/login">Back to Log in</a></p></section></div></main>
}

function OnboardingPage() {
  const steps = ['company', 'organization', 'work-policy', 'leave-policy', 'admin', 'employees']; const current = window.location.hash.split('/').pop(); const start = Math.max(0, steps.indexOf(current)); const [step, setStep] = useState(start); const [error, setError] = useState(''); const labels = ['Company', 'Organization', 'Work policy', 'Leave policy', 'Admin profile', 'Employees'];
  async function submit(event) { event.preventDefault(); setError(''); const form = new FormData(event.currentTarget); try { const path = [ENDPOINTS.company.create, ENDPOINTS.onboarding.organization, ENDPOINTS.onboarding.workPolicy, ENDPOINTS.onboarding.leavePolicy, ENDPOINTS.onboarding.admin, ENDPOINTS.onboarding.skipEmployees][step]; const body = step === 0 ? { name: form.get('name'), industry: form.get('industry'), company_size: form.get('size'), country: 'India', city: form.get('city'), timezone: 'Asia/Kolkata', currency: 'INR', fiscal_year_start_month: 4 } : step === 1 ? { departments: [{ name: form.get('department') }], designations: [{ name: form.get('designation'), level: 3 }], locations: [{ name: form.get('location'), city: form.get('city') }] } : step === 2 ? { working_days: [1,2,3,4,5], start_time: '09:30:00', end_time: '18:30:00', full_day_hours: 8, half_day_hours: 4, late_grace_minutes: 15 } : step === 3 ? { leave_types: [] } : step === 4 ? { first_name: form.get('first_name'), last_name: form.get('last_name'), phone: form.get('phone'), designation_name: form.get('designation'), joining_date: form.get('joining_date') } : {}; await api.post(path, body); if (step === 0) await refresh(); if (step === 5) window.location.hash = '#/dashboard'; else { const next = step + 1; setStep(next); window.location.hash = `#/onboarding/${steps[next]}` } } catch (err) { setError(err.message) } }
  return <main className="onboarding"><section><a className="brand" href="#/"><span className="brand-mark"><i></i><i></i><i></i></span><span>Luma<span>HR</span></span></a><p className="eyebrow">SET UP YOUR WORKSPACE</p><h1>{labels[step]}</h1><p>Step {step + 1} of 6. You can update these details later.</p><div className="onboard-progress"><span style={{ width: `${((step + 1) / 6) * 100}%` }} /></div><form className="onboard-form" onSubmit={submit}>{step === 0 && <><input name="name" placeholder="Company name" required/><input name="industry" placeholder="Industry" required/><select name="size"><option value="11-50">11–50 people</option><option value="1-10">1–10 people</option><option value="51-200">51–200 people</option></select><input name="city" placeholder="City" required/></>}{step === 1 && <><input name="department" placeholder="First department (e.g. Engineering)" required/><input name="designation" placeholder="First designation" required/><input name="location" placeholder="Office location" required/><input name="city" placeholder="City" required/></>}{step === 2 && <p className="onboard-note">Default schedule: Monday–Friday, 09:30–18:30 with an 8-hour workday.</p>}{step === 3 && <p className="onboard-note">We will use the seeded defaults: Casual Leave 12, Sick Leave 6, Earned Leave 15 and LWP.</p>}{step === 4 && <><input name="first_name" placeholder="First name" required/><input name="last_name" placeholder="Last name" required/><input name="phone" placeholder="Phone" required/><input name="designation" placeholder="Designation (e.g. Founder)" required/><input name="joining_date" type="date" required/></>}{step === 5 && <p className="onboard-note">You can add employees now from the HRMS after setup, or finish and invite them later.</p>}{error && <p className="form-error">{error}</p>}<button className="primary-button">{step === 5 ? 'Finish setup' : 'Continue'}</button></form></section></main>
}

function DashboardPage() {
  const initialRole = new URLSearchParams(window.location.hash.split('?')[1] || '').get('role')
  const [role] = useState(['employee', 'manager', 'hr'].includes(initialRole) ? initialRole : 'employee')
  const [checkedIn, setCheckedIn] = useState(false)
  const [toast, setToast] = useState('')
  const [activeNav, setActiveNav] = useState('Home')
  const roleConfig = {
    employee: ['EMPLOYEE WORKSPACE', ['Home', 'My profile', 'Attendance', 'Leave', 'Holidays', 'Payslips', 'Documents']],
    manager: ['MANAGER WORKSPACE', ['Home', 'My profile', 'Attendance', 'Leave', 'Holidays', 'Payslips', 'Documents', 'People']],
    hr: ['PEOPLE OPERATIONS', ['Home', 'People', 'Attendance', 'Leave', 'Holidays', 'Payroll', 'Reports', 'Documents', 'Settings', 'My profile']],
  }
  const [workspace, navItems] = roleConfig[role]
  function action(message) { const destinations = { 'Team directory opened': 'People', 'All team leave requests opened': 'Leave', 'Team attendance opened': 'Attendance', 'Time off request started': 'Leave', 'Announcement opened': 'Documents', 'Complete your profile updated': 'My profile' }; if (destinations[message]) setActiveNav(destinations[message]); setToast(message); window.setTimeout(() => setToast(''), 2800) }
  const content = activeNav === 'Home' ? (role === 'hr' ? <HRDashboardHome action={action} /> : role === 'manager' ? <ManagerDashboardHome action={action} /> : <DashboardHome checkedIn={checkedIn} setCheckedIn={setCheckedIn} action={action} />) : activeNav === 'My profile' ? <ProfilePage action={action} role={role} /> : activeNav === 'Attendance' ? (role === 'hr' ? <HRAttendancePage action={action} /> : role === 'manager' ? <ManagerAttendancePage action={action} /> : <AttendancePage action={action} role={role} />) : activeNav === 'Leave' ? (role === 'hr' ? <HRLeavePage action={action} /> : role === 'manager' ? <ManagerLeavePage action={action} /> : <EnhancedLeavePage action={action} role={role} />) : activeNav === 'Holidays' ? <HolidaysPage action={action} role={role} /> : activeNav === 'Payslips' ? <PayslipsPage action={action} /> : activeNav === 'Documents' ? <DocumentsPage action={action} role={role} /> : activeNav === 'People' ? (role === 'manager' ? <ManagerPeoplePage action={action} /> : <HRPeoplePage action={action} />) : activeNav === 'Payroll' ? <PayrollPage action={action} /> : activeNav === 'Reports' ? <ReportsPage action={action} /> : activeNav === 'Settings' ? <SettingsPage action={action} /> : <RedesignedModulePage page={activeNav} action={action} role={role} />
  return <main className="dashboard"><aside className="dash-sidebar"><a className="brand dash-brand" href="#/"><span className="brand-mark"><i></i><i></i><i></i></span><span>Luma<span>HR</span></span></a><p className="dash-workspace">{workspace}</p><nav aria-label="Workspace navigation">{navItems.map(item => <button key={item} className={activeNav === item ? 'active' : ''} onClick={() => setActiveNav(item)}>{item}</button>)}</nav><div className="dash-help"><b>Need a hand?</b><p>Visit the Help Centre or ask your people team.</p><button onClick={() => action('Help request started')}>Get support →</button></div><a className="dash-user" href="#/login"><span>MA</span><div><b>Maya Allen</b><small>{role === 'hr' ? 'People Operations' : role === 'manager' ? 'Team Manager' : 'Product Design'}</small></div><i>⌄</i></a></aside><section className="dash-main"><header className="dash-top"><div><p>Thursday, 14 August</p><h1>{activeNav === 'Home' ? (role === 'hr' ? 'Your people are in motion.' : 'Good morning, Maya.') : activeNav}</h1></div><DashboardTools onNavigate={setActiveNav} action={action} role={role} /></header>{content}</section>{toast && <div className="dash-toast" role="status">{toast}</div>}</main>
}

function HRDashboardLegacy({ action }) { return <><section className="hr-overview"><div><p className="eyebrow">TODAY AT NORTHSTAR</p><h2>Here’s the shape of your team.</h2><p>Clear signals for the things that need your attention.</p></div><button className="primary-button" onClick={() => action('People directory opened')}>View people</button></section><section className="hr-stat-grid">{[['48', 'Total employees', '46 active'], ['41', 'Present today', '4 working remotely'], ['7', 'Leave approvals', 'Needs review'], ['1', 'Payroll run', 'August draft']].map(([number, label, hint]) => <article key={label}><strong>{number}</strong><b>{label}</b><small>{hint}</small></article>)}</section><section className="hr-work-grid"><article><div className="card-heading"><div><p className="eyebrow">APPROVAL INBOX</p><h3>Leave requests waiting.</h3></div><button onClick={() => action('Leave approval inbox opened')}>View all</button></div>{[['Aisha Rao', '2 days · 21–22 Aug'], ['Rohan Shah', '1 day · 27 Aug'], ['Jules Martin', 'Half day · 30 Aug']].map(([name, detail]) => <div className="approval-row" key={name}><span>{name.split(' ').map(x => x[0]).join('')}</span><p><b>{name}</b><small>{detail}</small></p><button onClick={() => action(`${name}'s leave approved`)}>Approve</button></div>)}</article><article><p className="eyebrow">TEAM SNAPSHOT</p><h3>Today’s attendance mix.</h3><div className="attendance-bars"><p><span>Present</span><i><b style={{ width: '85%' }} /></i><strong>41</strong></p><p><span>WFH</span><i><b style={{ width: '38%' }} /></i><strong>4</strong></p><p><span>On leave</span><i><b style={{ width: '29%' }} /></i><strong>3</strong></p><p><span>Late</span><i><b style={{ width: '46%' }} /></i><strong>5</strong></p></div><button className="text-action" onClick={() => action('Attendance report opened')}>Open attendance report</button></article></section></> }

function ManagerDashboardHome({ action }) { const [approvals, setApprovals] = useState([['Jules Martin', '2 days · 21–22 Aug', 'JM'], ['Rohan Shah', 'Half day · 27 Aug', 'RS']]); const approve = name => { setApprovals(current => current.filter(([person]) => person !== name)); action(`${name}'s leave approved`) }; return <section className="manager-dashboard"><section className="manager-hero"><div><p className="eyebrow">YOUR TEAM · PRODUCT DESIGN</p><h2>Keep the team moving with care.</h2><p>See who needs attention, celebrate progress, and make the next decision clear.</p></div><button className="primary-button" onClick={() => action('Team directory opened')}>View my team</button></section><section className="manager-stats">{[['8', 'Direct reports', 'All active'], ['7', 'Working today', '1 remote'], [String(approvals.length), 'Leave approvals', 'Waiting for you'], ['1', 'Check-in missing', 'Needs follow-up']].map(([value, label, hint]) => <article key={label}><strong>{value}</strong><b>{label}</b><small>{hint}</small></article>)}</section><section className="manager-grid"><article className="manager-approvals"><div className="card-heading"><div><p className="eyebrow">APPROVAL INBOX</p><h3>Make time off easy.</h3></div><button onClick={() => action('All team leave requests opened')}>View all</button></div>{approvals.length ? approvals.map(([name, detail, initials]) => <div className="manager-request" key={name}><span>{initials}</span><p><b>{name}</b><small>{detail}</small></p><div><button className="approve" onClick={() => approve(name)}>Approve</button><button className="decline" onClick={() => action(`Add comment for ${name}`)}>Comment</button></div></div>) : <div className="manager-empty"><b>You’re all caught up.</b><small>No leave requests need approval right now.</small></div>}</article><article className="manager-availability"><p className="eyebrow">TEAM AVAILABILITY</p><h3>Today’s rhythm.</h3>{[['Aisha Rao', 'Online · In the studio', 'online'], ['Jules Martin', 'Working from home', 'wfh'], ['Maya Allen', 'Online · In the studio', 'online'], ['Rohan Shah', 'Checked in at 09:18', 'late']].map(([name, detail, state]) => <div key={name}><span className={state}></span><p><b>{name}</b><small>{detail}</small></p></div>)}<button className="text-action" onClick={() => action('Team attendance opened')}>Open team attendance</button></article></section><section className="manager-bottom"><article><p className="eyebrow">TEAM MOMENT</p><h3>Jules celebrates 3 years this week.</h3><p>Send a thoughtful note to make the moment count.</p><button onClick={() => action('Celebration sent to Jules')}>Celebrate Jules</button></article><article><p className="eyebrow">MANAGER CHECKLIST</p>{['Review two leave requests', 'Share weekly priorities', 'Book 1:1 with Rohan'].map(item => <label key={item}><input type="checkbox" onChange={() => action(`${item} updated`)} /><span>{item}</span></label>)}</article></section></section> }

function DashboardToolsLegacy({ onNavigate, action, role }) {
  const [searchOpen, setSearchOpen] = useState(false)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [query, setQuery] = useState('')
  const searchItems = role === 'hr' ? [['People directory', 'Browse employees and teams', 'People'], ['Attendance overview', 'Team time and status', 'Attendance'], ['Leave approvals', '7 requests need review', 'Leave'], ['August payroll', 'Draft payroll run', 'Payroll'], ['Reports', 'People analytics and exports', 'Reports'], ['Company settings', 'Policies and organisation', 'Settings'], ['Benefits guide', 'Updated company document', 'Documents']] : role === 'manager' ? [['My profile', 'Employee profile', 'My profile'], ['Team attendance', 'Your team time and status', 'Attendance'], ['Leave approvals', 'Requests needing review', 'Leave'], ['People directory', 'Your direct reports', 'People'], ['Payslips', 'Your latest pay statement', 'Payslips'], ['Benefits guide', 'Updated company document', 'Documents']] : [['Maya Allen', 'Employee profile', 'My profile'], ['Attendance', 'Track your time and check-ins', 'Attendance'], ['Leave balance', '14 days available', 'Leave'], ['July payslip', 'Your latest pay statement', 'Payslips'], ['Benefits guide', 'Updated company document', 'Documents']]
  const results = searchItems.filter(([name, detail]) => `${name} ${detail}`.toLowerCase().includes(query.toLowerCase())).slice(0, 5)
  const choose = (page, label) => { onNavigate(page); setSearchOpen(false); setQuery(''); action(`${label} opened`) }
  return <div className="dash-actions"><div className="dash-tool"><button className="top-action" onClick={() => { setSearchOpen(!searchOpen); setNotificationsOpen(false) }} aria-label="Search workspace" aria-expanded={searchOpen}>Search</button>{searchOpen && <div className="dash-popover search-popover"><label htmlFor="workspace-search">Search workspace</label><input id="workspace-search" autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="People, documents, pages..." />{results.length ? <div className="search-results">{results.map(([name, detail, page]) => <button key={name} onClick={() => choose(page, name)}><b>{name}</b><small>{detail}</small></button>)}</div> : <p className="empty-search">No matching workspace items.</p>}</div>}</div><div className="dash-tool"><button className="top-action notification-action" onClick={() => { setNotificationsOpen(!notificationsOpen); setSearchOpen(false) }} aria-label="Notifications" aria-expanded={notificationsOpen}>Alerts<span>3</span></button>{notificationsOpen && <div className="dash-popover notification-popover"><div className="popover-title"><div><b>Notifications</b><small>3 unread updates</small></div><button onClick={() => action('All notifications marked as read')}>Mark all read</button></div>{[['Leave request pending', 'Aisha requested 2 days', 'Leave'], ['Payslip generated', 'July payslip is ready', 'Payslips'], ['Document updated', 'Benefits guide was refreshed', 'Documents']].map(([title, detail, page]) => <button className="notification-item" key={title} onClick={() => { onNavigate(page); setNotificationsOpen(false); action(title) }}><span></span><div><b>{title}</b><small>{detail}</small></div></button>)}</div>}</div><a href="#/">Exit workspace</a></div>
}

function DashboardHome({ checkedIn, setCheckedIn, action }) { return <><section className="dash-focus"><div><p className="eyebrow">YOUR DAY, AT A GLANCE</p><h2>Small moments. Stronger teams.</h2><p>Three thoughtful things are ready for you today.</p><div className="focus-progress"><span></span></div><small>2 of 3 moments completed</small></div><button className={checkedIn ? 'checkin checked' : 'checkin'} onClick={() => { setCheckedIn(!checkedIn); action(checkedIn ? 'Check-in removed' : 'Checked in at 9:04 AM') }}><span>{checkedIn ? '✓' : '◷'}</span><b>{checkedIn ? 'Checked in' : 'Check in'}</b><small>{checkedIn ? '9:04 AM today' : 'Start your day'}</small></button></section><section className="dash-grid"><article className="leave-card"><div className="card-heading"><div><p className="eyebrow">TIME OFF</p><h3>Take a breather.</h3></div><button onClick={() => action('Time off request started')}>Request time off</button></div><div className="leave-metrics"><div><strong>14</strong><span>days available</span></div><div><strong>2</strong><span>upcoming days</span></div><div><strong>0</strong><span>pending requests</span></div></div><div className="leave-next"><span>21</span><p><b>Mon, 21 Aug</b><small>Summer bank holiday</small></p><i>→</i></div></article><article className="tasks-card"><div className="card-heading"><div><p className="eyebrow">YOUR NEXT STEPS</p><h3>Keep the good work moving.</h3></div><button onClick={() => action('Tasks marked as read')}>View all</button></div>{['Review your growth goals', 'Share feedback for Jules', 'Complete your profile'].map((task, i) => <label className="task" key={task}><input type="checkbox" onChange={() => action(i === 0 ? 'Goal review complete' : 'Task updated')}/><span>{task}</span><small>{i === 0 ? 'Due today' : i === 1 ? '2 min' : 'Optional'}</small></label>)}</article></section><section className="dash-bottom"><article className="celebrate-card"><p className="eyebrow">TEAM MOMENT</p><div><span>J</span><p><b>Jules is celebrating 3 years!</b><small>Send a little appreciation their way.</small></p><button onClick={() => action('Celebration sent to Jules!')}>Celebrate</button></div></article><article className="notice-card"><p className="eyebrow">FROM YOUR PEOPLE TEAM</p><h3>New learning days are here.</h3><p>Set aside time for the skills you want to grow next.</p><button onClick={() => action('Announcement opened')}>Read the update →</button></article></section></> }

function PayrollPage({ action }) {
  const [selected, setSelected] = useState(null); const [runs, setRuns] = useState([{ month: 'August 2026', status: 'DRAFT', people: '48 employees', total: 'INR 36.2L', date: 'Pay date · 25 Aug' }, { month: 'July 2026', status: 'PAID', people: '46 employees', total: 'INR 34.8L', date: 'Paid · 25 Jul' }, { month: 'June 2026', status: 'PAID', people: '45 employees', total: 'INR 33.9L', date: 'Paid · 25 Jun' }]); const process = () => { setRuns(current => current.map((run, index) => index === 0 ? { ...run, status: 'PENDING REVIEW' } : run)); action('August payroll submitted for review') }
  return <section className="payroll-page"><section className="payroll-hero"><div><p className="eyebrow">PAYROLL WORKSPACE</p><h2>Payday, without the scramble.</h2><p>Review payroll runs, resolve exceptions, and give every person confidence in their pay.</p></div><button className="primary-button" onClick={process}>Process August payroll</button></section><section className="payroll-stats"><article><strong>48</strong><span>People in August run</span></article><article><strong>36.2L</strong><span>Estimated net payout</span></article><article><strong>1</strong><span>Run awaiting review</span></article><article><strong>25 Aug</strong><span>Next pay date</span></article></section><section className="payroll-runs"><div className="payroll-runs-head"><div><p className="eyebrow">PAYROLL RUNS</p><h3>Monthly payroll history</h3></div><button onClick={() => action('Payroll summary exported')}>Export summary</button></div>{runs.map(run => <article key={run.month}><span className="payroll-icon">INR</span><div><b>{run.month}</b><small>{run.people} · {run.date}</small></div><strong>{run.total}</strong><em className={run.status.toLowerCase().replaceAll(' ', '-')}>{run.status}</em><button onClick={() => setSelected(run)}>View run</button></article>)}</section>{selected && <section className="payroll-detail"><div><p className="eyebrow">PAYROLL RUN</p><h3>{selected.month}</h3><p>{selected.people} · {selected.total}</p><small>{selected.date} · Status: {selected.status}</small></div><div><button className="primary-button" onClick={() => action(`${selected.month} payslips generated`)}>Generate payslips</button><button onClick={() => setSelected(null)}>Close</button></div></section>}<section className="payroll-note"><div><p className="eyebrow">PAYROLL CHECK</p><h3>August run is ready to review.</h3><p>One draft run with 48 people is waiting for the final review before approval.</p></div><button onClick={() => setSelected(runs[0])}>Review draft run</button></section></section>
}

function ReportsPage({ action }) {
  const [range, setRange] = useState('Last 30 days'); const [department, setDepartment] = useState('All departments'); const [selected, setSelected] = useState(null)
  const reports = [{ title: 'Headcount report', text: 'Employees, joins, exits, and team distribution.', type: 'PEOPLE', updated: 'Updated today' }, { title: 'Attendance report', text: 'Working hours, presence, and exceptions by team.', type: 'TIME', updated: 'Updated 10 min ago' }, { title: 'Leave report', text: 'Balances, requests, and time-off trends.', type: 'LEAVE', updated: 'Updated today' }, { title: 'Payroll summary', text: 'Monthly cost, payouts, and payroll exceptions.', type: 'PAY', updated: 'Updated 25 Jul' }]
  const exportReport = report => { const content = `LumaHR ${report.title}\nRange: ${range}\nDepartment: ${department}\nGenerated: 14 August 2026\n\nThis is a frontend demo export.`; const url = URL.createObjectURL(new Blob([content], { type: 'text/plain;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = `${report.title.toLowerCase().replaceAll(' ', '-')}.txt`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); action(`${report.title} downloaded`) }
  return <section className="reports-page"><section className="reports-hero"><div><p className="eyebrow">PEOPLE ANALYTICS</p><h2>Know what your people need.</h2><p>Track the signals behind a healthier, more supported workplace.</p></div><button className="primary-button" onClick={() => exportReport({ title: 'People insights overview' })}>Export overview</button></section><section className="report-controls"><label>Period<select value={range} onChange={event => setRange(event.target.value)}><option>Last 30 days</option><option>This quarter</option><option>This year</option></select></label><label>Team<select value={department} onChange={event => setDepartment(event.target.value)}><option>All departments</option><option>Product Design</option><option>Engineering</option><option>Operations</option></select></label><span>Showing {range.toLowerCase()} · {department}</span></section><section className="report-metrics"><article><small>ACTIVE HEADCOUNT</small><strong>48</strong><span>+4 since January</span></article><article><small>ATTENDANCE RATE</small><strong>96%</strong><span>Up 2.1% this period</span></article><article><small>LEAVE UTILISATION</small><strong>62%</strong><span>Healthy seasonal use</span></article><article><small>TEAM PULSE</small><strong>8.7</strong><span>Out of 10 this month</span></article></section><section className="report-grid"><section className="report-chart"><div><p className="eyebrow">HEADCOUNT TREND</p><h3>Steady, intentional growth.</h3><p>Team size over the past six months.</p></div><div className="chart-bars">{[['Mar',34],['Apr',36],['May',39],['Jun',42],['Jul',45],['Aug',48]].map(([month,value]) => <div key={month}><span style={{ height: `${value * 2}px` }}><i>{value}</i></span><small>{month}</small></div>)}</div></section><section className="report-insight"><p className="eyebrow">AN INSIGHT</p><h3>Product Design is taking time off early.</h3><p>62% of their annual leave is already planned. Their next busy period begins in September.</p><button onClick={() => action('Leave planning view opened')}>Review leave plan →</button></section></section><section className="report-library"><div className="report-library-head"><div><p className="eyebrow">REPORT LIBRARY</p><h3>Useful data, ready when you are.</h3></div><span>{reports.length} available</span></div>{reports.map(report => <article key={report.title}><span>{report.type}</span><div><b>{report.title}</b><small>{report.text} · {report.updated}</small></div><button onClick={() => setSelected(report)}>Preview</button><button className="report-export" onClick={() => exportReport(report)}>Export</button></article>)}</section>{selected && <section className="report-preview"><div><p className="eyebrow">REPORT PREVIEW</p><h3>{selected.title}</h3><p>{selected.text}</p><small>{selected.updated} · {range} · {department}</small></div><div><button className="primary-button" onClick={() => exportReport(selected)}>Download report</button><button onClick={() => setSelected(null)}>Close</button></div></section>}</section>
}

function SettingsPage({ action }) {
  const [section, setSection] = useState('Organisation'); const [companyName, setCompanyName] = useState('Northstar Studio'); const [enabled, setEnabled] = useState({ digest: true, leave: true, payroll: true, birthday: false }); const [saved, setSaved] = useState(false)
  const settings = { Organisation: { title: 'Organisation profile', text: 'The basics that make your workspace yours.' }, Policies: { title: 'People policies', text: 'Set clear, consistent defaults for everyone.' }, Notifications: { title: 'Notification preferences', text: 'Choose which moments need a nudge.' }, Access: { title: 'Roles & access', text: 'Give people the right level of access.' } }
  const save = () => { setSaved(true); action(`${settings[section].title} saved`); window.setTimeout(() => setSaved(false), 2200) }
  return <section className="settings-page"><section className="settings-hero"><div><p className="eyebrow">WORKSPACE SETTINGS</p><h2>Make LumaHR work your way.</h2><p>Shape your organisation, policies, and everyday people operations from one calm place.</p></div><span>Admin workspace</span></section><section className="settings-layout"><nav className="settings-nav">{Object.keys(settings).map(item => <button key={item} className={section === item ? 'active' : ''} onClick={() => setSection(item)}>{item}<small>{item === 'Organisation' ? 'Company details' : item === 'Policies' ? 'Time off & attendance' : item === 'Notifications' ? 'Team updates' : 'Permissions'}</small></button>)}</nav><section className="settings-panel"><div className="settings-panel-head"><div><p className="eyebrow">{section.toUpperCase()}</p><h3>{settings[section].title}</h3><p>{settings[section].text}</p></div><button className="primary-button" onClick={save}>{saved ? 'Saved ✓' : 'Save changes'}</button></div>{section === 'Organisation' && <div className="settings-form"><label>Organisation name<input value={companyName} onChange={event => setCompanyName(event.target.value)} /></label><label>Primary location<select defaultValue="Pune, India"><option>Pune, India</option><option>Bengaluru, India</option><option>Remote</option></select></label><label>Working week<select defaultValue="Monday to Friday"><option>Monday to Friday</option><option>Monday to Saturday</option></select></label><label>Company size<select defaultValue="26–50 people"><option>1–25 people</option><option>26–50 people</option><option>51–100 people</option></select></label><section><p className="eyebrow">WORKSPACE ID</p><b>northstar-studio</b><small>Used for your team’s private LumaHR workspace.</small></section></div>}{section === 'Policies' && <div className="settings-cards">{[['Leave year','1 January – 31 December','Annual leave balances reset on 1 January.'],['Standard workday','8 hours · Monday to Friday','Used for attendance and hours calculations.'],['Approval flow','Manager → People Operations','One approval step is active for leave requests.']].map(([title,value,text]) => <article key={title}><div><b>{title}</b><strong>{value}</strong><small>{text}</small></div><button onClick={() => action(`${title} edit opened`)}>Edit</button></article>)}</div>}{section === 'Notifications' && <div className="settings-toggles">{[['digest','Weekly people digest','A concise Friday summary for managers and admins.'],['leave','Leave request updates','Notify approvers when a request needs attention.'],['payroll','Payroll review reminders','Send reminders before every pay date.'],['birthday','Birthday & anniversary moments','Celebrate milestones in the team feed.']].map(([key,title,text]) => <article key={key}><div><b>{title}</b><small>{text}</small></div><button className={enabled[key] ? 'toggle on' : 'toggle'} aria-label={`Toggle ${title}`} onClick={() => setEnabled(current => ({ ...current, [key]: !current[key] }))}><i></i></button></article>)}</div>}{section === 'Access' && <div className="settings-cards">{[['People Operations','Full workspace access','2 admins'],['Managers','Team-only people data','6 managers'],['Employees','Personal workspace access','40 employees']].map(([title,value,text]) => <article key={title}><div><b>{title}</b><strong>{value}</strong><small>{text}</small></div><button onClick={() => action(`${title} permissions opened`)}>Manage</button></article>)}</div>}</section></section></section>
}

function HRLeaveLegacy({ action }) {
  const [department, setDepartment] = useState('All departments'); const [requests, setRequests] = useState([{ id: 1, name: 'Jules Martin', initials: 'JM', dept: 'Product Design', dates: '21–22 Aug', type: 'Casual Leave · 2 days', reason: 'Family function' }, { id: 2, name: 'Rohan Shah', initials: 'RS', dept: 'Engineering', dates: '27 Aug', type: 'Sick Leave · 1 day', reason: 'Medical appointment' }, { id: 3, name: 'Neha Kapoor', initials: 'NK', dept: 'Product Design', dates: '30 Aug', type: 'Half day · Second half', reason: 'Personal errand' }]); const [selected, setSelected] = useState(null); const [comment, setComment] = useState('')
  const shown = requests.filter(item => department === 'All departments' || item.dept === department); const decide = decision => { setRequests(current => current.filter(item => item.id !== selected.id)); action(`${selected.name}'s leave ${decision.toLowerCase()}`); setSelected(null); setComment('') }
  return <section className="hr-leave"><section className="hr-attendance-hero"><div><p className="eyebrow">COMPANY LEAVE</p><h2>Keep every absence in balance.</h2><p>Review company-wide requests, protect coverage, and support your people.</p></div><button className="primary-button" onClick={() => action('Leave policy settings opened')}>Manage leave policy</button></section><section className="hr-attendance-stats">{[[String(requests.length), 'Pending approvals'], ['3', 'On leave today'], ['24', 'Requests this month'], ['4', 'Leave types']].map(([number, label]) => <article key={label}><strong>{number}</strong><span>{label}</span></article>)}</section><section className="hr-leave-list"><div className="hr-attendance-toolbar"><div><p className="eyebrow">APPROVAL INBOX</p><h3>Requests needing review</h3></div><div><select value={department} onChange={event => setDepartment(event.target.value)}><option>All departments</option><option>Product Design</option><option>Engineering</option></select><button onClick={() => action('Leave history exported')}>Export</button></div></div>{shown.map(request => <article key={request.id}><span>{request.initials}</span><div><b>{request.name}</b><small>{request.dept} · {request.dates} · {request.type}</small></div><em>PENDING</em><button onClick={() => setSelected(request)}>Review</button></article>)}{!shown.length && <p className="hr-people-empty">No requests match this filter.</p>}</section>{selected && <section className="hr-leave-detail"><div><span>{selected.initials}</span><div><p className="eyebrow">LEAVE REQUEST</p><h3>{selected.name}</h3><p>{selected.dept} · {selected.dates} · {selected.type}</p><small>Reason: {selected.reason}</small></div></div><label>Decision comment<textarea value={comment} onChange={event => setComment(event.target.value)} placeholder="Optional when approving, required when rejecting" /></label><div><button className="primary-button" onClick={() => decide('Approved')}>Approve</button><button className="hr-reject" onClick={() => comment.trim() ? decide('Rejected') : action('Add a rejection comment first')}>Reject</button><button onClick={() => setSelected(null)}>Close</button></div></section>}<section className="hr-leave-override"><div><p className="eyebrow">BALANCE MANAGEMENT</p><h3>Need to correct a leave balance?</h3><p>Open the employee record to adjust annual allocations or carry-forward days.</p></div><button onClick={() => action('Leave balance override opened')}>Open balance override</button></section></section>
}

