  const holidays = [{ date: '15', month: 'AUG', day: 'Friday', name: 'Independence Day', type: 'Public holiday', scope: 'Company-wide' }, { date: '19', month: 'AUG', day: 'Tuesday', name: 'Raksha Bandhan', type: 'Optional holiday', scope: 'Pune location' }, { date: '27', month: 'AUG', day: 'Wednesday', name: 'Ganesh Chaturthi', type: 'Public holiday', scope: 'Company-wide' }, { date: '02', month: 'OCT', day: 'Thursday', name: 'Gandhi Jayanti', type: 'Public holiday', scope: 'Company-wide' }, { date: '25', month: 'DEC', day: 'Friday', name: 'Christmas Day', type: 'Public holiday', scope: 'Company-wide' }]
