function ManagerPeoplePage({ action }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All people'); const [selected, setSelected] = useState(null); const [updateOpen, setUpdateOpen] = useState(false); const [updates, setUpdates] = useState([])
  const people = [{ name: 'Jules Martin', initials: 'JM', title: 'Product Designer', work: 'Pune · Hybrid', status: 'Working from home', group: 'Remote', joined: '04 May 2023', email: 'jules@northstar.studio' }, { name: 'Maya Allen', initials: 'MA', title: 'Product Designer', work: 'Pune · Office', status: 'In the studio', group: 'Office', joined: '12 Jan 2024', email: 'maya@northstar.studio' }, { name: 'Rohan Shah', initials: 'RS', title: 'Engineering Lead', work: 'Pune · Office', status: 'Late check-in', group: 'Office', joined: '18 Sep 2022', email: 'rohan@northstar.studio' }, { name: 'Neha Kapoor', initials: 'NK', title: 'Product Researcher', work: 'Pune · On leave', status: 'Casual leave', group: 'Leave', joined: '06 Jun 2024', email: 'neha@northstar.studio' }]
  const filtered = people.filter(person => person.name.toLowerCase().includes(query.toLowerCase()) && (filter === 'All people' || person.group === filter)); const share = event => { event.preventDefault(); const form = new FormData(event.currentTarget); const message = String(form.get('message') || '').trim(); if (!message) return action('Write an update before sharing'); setUpdates(current => [{ id: Date.now(), title: form.get('title') || 'Team update', message }, ...current]); setUpdateOpen(false); action('Team update shared') }
  return <section className="manager-people"><section className="manager-people-hero"><div><p className="eyebrow">MY TEAM</p><h2>People doing their best work.</h2><p>Keep your direct reports connected, supported, and moving forward.</p></div><button className="primary-button" onClick={() => setUpdateOpen(!updateOpen)}>{updateOpen ? 'Close update' : 'Share team update'}</button></section>{updateOpen && <form className="team-update-form" onSubmit={share}><label>Update title<input name="title" placeholder="e.g. This week in Product Design" /></label><label>Message<textarea name="message" required placeholder="Share a priority, win, or useful context with the team." /></label><div><label><input type="checkbox" name="notify" defaultChecked /> Notify the team</label><button className="primary-button">Share update</button></div></form>}{updates.map(update => <section className="team-update-post" key={update.id}><p className="eyebrow">JUST SHARED</p><h3>{update.title}</h3><p>{update.message}</p></section>)}<section className="manager-people-stats"><article><strong>8</strong><span>Direct reports</span></article><article><strong>6</strong><span>In office today</span></article><article><strong>1</strong><span>Working remotely</span></article><article><strong>1</strong><span>On leave</span></article></section><section className="manager-people-directory"><div className="manager-people-toolbar"><div><p className="eyebrow">DIRECT REPORTS</p><h3>Team directory</h3></div><div><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search your team" /><select value={filter} onChange={event => setFilter(event.target.value)}><option>All people</option><option>Office</option><option>Remote</option><option>Leave</option></select></div></div><div className="manager-people-grid">{filtered.map(person => <article key={person.name}><span className="manager-person-avatar">{person.initials}</span><div><b>{person.name}</b><small>{person.title}</small><p>{person.work}</p></div><em className={person.group.toLowerCase()}>{person.status}</em><button onClick={() => setSelected(person)}>View profile</button></article>)}</div>{!filtered.length && <p className="manager-people-empty">No direct reports match those filters.</p>}</section>{selected && <section className="manager-people-detail"><div><span className="manager-person-avatar">{selected.initials}</span><div><p className="eyebrow">TEAM MEMBER</p><h3>{selected.name}</h3><p>{selected.title} · {selected.work}</p><small>{selected.email} · Joined {selected.joined}</small></div></div><div><button className="primary-button" onClick={() => action(`1:1 with ${selected.name} started`)}>Schedule 1:1</button><button onClick={() => setSelected(null)}>Close</button></div></section>}</section>
}
